//! VEILOS `d3d9.dll`: Direct3D 9 (WIN32_DESIGN.md G5d).
//!
//! The fixed-function pipeline runs here, in user mode with real floating
//! point; what comes out is window-space primitives in fixed point, drawn by
//! the kernel's rasterizer (src/raster3d.rs, through VEIL_GPU3D) on every
//! CPU, with Direct3D's texture stages as its own combiner. Frames are shown
//! with StretchDIBits at Present.
//!
//!   com.rs     COM objects, references, IUnknown and IDirect3DResource9
//!   vtbl.rs    the vtables (generated by gen_vtbl.py from interfaces.txt)
//!   d3d.rs     IDirect3D9: the adapter, modes, formats, caps, CreateDevice
//!   device.rs  IDirect3DDevice9: state, targets, state blocks, queries
//!   state.rs   the device state, its defaults, state blocks
//!   res.rs     surfaces, textures, buffers, declarations, copies
//!   format.rs  pixel formats, DXT
//!   draw.rs    the pipeline, draw calls, Clear, Present
//!
//! Not yet: shaders (G5e), volume textures, cube map sampling, multisampling,
//! vertex blending, and more than one swap chain.

#![no_std]
#![allow(non_snake_case, clippy::missing_safety_doc, clippy::too_many_arguments)]

extern crate alloc;

#[path = "../../dllrt.rs"]
mod dllrt;
mod com;
mod d3d;
mod device;
mod draw;
mod format;
mod res;
mod state;
mod vtbl;

use com::*;

static D3D_IIDS: [Guid; 1] = [IID_D3D9];

#[no_mangle]
pub extern "system" fn DllMain(_module: usize, _reason: u32, _reserved: usize) -> i32 {
    1
}

#[no_mangle]
pub extern "system" fn Direct3DCreate9(_sdk: u32) -> *mut Com {
    Com::new(&vtbl::IDIRECT3D9, &D3D_IIDS, core::ptr::null_mut(), Body::D3D)
}

/// Direct3D 9Ex isn't here: programs fall back to Direct3DCreate9.
#[no_mangle]
pub extern "system" fn Direct3DCreate9Ex(_sdk: u32, out: *mut *mut Com) -> i32 {
    if !out.is_null() {
        unsafe { *out = core::ptr::null_mut() };
    }
    D3DERR_NOTAVAILABLE
}

#[no_mangle]
pub extern "system" fn Direct3DCreate9On12(_sdk: u32, _args: usize, _n: u32) -> *mut Com {
    core::ptr::null_mut()
}

#[no_mangle]
pub extern "system" fn Direct3DCreate9On12Ex(sdk: u32, _args: usize, _n: u32, out: *mut *mut Com) -> i32 {
    Direct3DCreate9Ex(sdk, out)
}

